/**
 * Command labels built from a template. `$1` in the translation is replaced by the
 * captured part, after it has been translated itself (interval names, for example).
 */
export const LABEL_PATTERNS: { re: RegExp; to: [string, string, string] }[] = [
  { re: /^Write ([A-G])$/, to: ['Écrire $1', 'Escribir $1', '$1 schreiben'] },
  { re: /^Add ([A-G]) to chord$/, to: ['Ajouter $1 à l’accord', 'Añadir $1 al acorde', '$1 zum Akkord hinzufügen'] },
  { re: /^Add interval: (.+) above$/, to: ['Ajouter une $1 au-dessus', 'Añadir una $1 encima', '$1 darüber hinzufügen'] },
  { re: /^Dynamic (.+)$/, to: ['Nuance $1', 'Dinámica $1', 'Dynamik $1'] },
  { re: /^(D\.[CS]\..*) \(end of this bar\)$/, to: ['$1 (fin de cette mesure)', '$1 (final de este compás)', '$1 (Ende dieses Takts)'] },
];

